const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const PW=process.env.ADMIN_PASSWORD||'ECS2026',PORT=process.env.PORT||3000,DB=process.env.DATA_FILE||path.join(__dirname,'data.json');
const PUB=path.join(__dirname,'public'),ADM=path.join(__dirname,'admin');
for(const f of [path.join(PUB,'index.html'),path.join(ADM,'index.html')])if(!fs.existsSync(f))console.log('NOTE: '+f+' not found on disk - serving the built-in copy instead. Commit the public/ and admin/ folders to GitHub to use your own files.');
// Built-in copy of the site files, used ONLY if the real files are missing from the deploy. Refresh with: node embed.js
const EMBED=/*EMBED_START*/{"data.json":"","public/app.js":"","public/common.js":"","public/hero.jpg":"","public/index.html":"","public/style.css":"","admin/admin.css":"","admin/app.js":"","admin/index.html":""}/*EMBED_END*/;
const fromEmbed=rel=>EMBED[rel]?Buffer.from(EMBED[rel],'base64'):null;
let state={teams:[],groups:[],fixtures:[],live:null,history:[]};
try{state=JSON.parse(fs.readFileSync(DB))}catch(e){try{state=JSON.parse(fromEmbed('data.json')||JSON.stringify(state))}catch(_){}try{fs.writeFileSync(DB,JSON.stringify(state))}catch(_){}}
const tokens=new Map(),fails=new Map(),types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.jpg':'image/jpeg','.svg':'image/svg+xml'};
const send=(r,c,b,t='application/json',h={})=>{r.writeHead(c,{'Content-Type':t,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...h});r.end(typeof b=='string'||Buffer.isBuffer(b)?b:JSON.stringify(b))};
const same=(a,b)=>crypto.timingSafeEqual(crypto.createHash('sha256').update(String(a)).digest(),crypto.createHash('sha256').update(String(b)).digest());
const valid=j=>j&&typeof j=='object'&&['teams','groups','fixtures','history'].every(k=>Array.isArray(j[k]));
function persist(){const t=DB+'.tmp';fs.writeFileSync(t,JSON.stringify(state));fs.renameSync(t,DB)}
http.createServer((q,r)=>{
 const u=q.url.split('?')[0];
 if(u=='/api/state'&&q.method=='GET')return send(r,200,state);
 if(q.method=='POST'&&(u=='/api/login'||u=='/api/state')){let b='',big=0;q.on('data',d=>{b+=d;if(b.length>2e7){big=1;q.destroy()}});q.on('end',()=>{if(big)return;try{const j=JSON.parse(b);
  if(u=='/api/login'){const ip=q.socket.remoteAddress,f=fails.get(ip)||{n:0,t:Date.now()};if(Date.now()-f.t>6e4){f.n=0;f.t=Date.now()}
   if(f.n>=10)return send(r,429,{error:'Too many attempts. Wait a minute.'});
   if(same(j.password||'',PW)){fails.delete(ip);const t=crypto.randomBytes(24).toString('hex');tokens.set(t,Date.now()+12*36e5);return send(r,200,{token:t})}
   f.n++;fails.set(ip,f);return send(r,401,{error:'Wrong password'})}
  const exp=tokens.get(q.headers['x-token']);if(!exp||exp<Date.now())return send(r,401,{error:'Login required'});
  if(!valid(j))return send(r,400,{error:'Invalid data'});
  state=j;persist();send(r,200,{ok:1})}catch(e){send(r,400,{error:'Bad request'})}});return}
 if(q.method!='GET'&&q.method!='HEAD')return send(r,405,{error:'Method not allowed'});
 const f=u=='/admin'||u=='/admin/'?path.join(ADM,'index.html'):u=='/'||u=='/index.html'?path.join(PUB,'index.html'):u.startsWith('/admin/')?path.join(ADM,u.slice(7)):path.join(PUB,u);
 if(!f.startsWith(PUB+path.sep)&&!f.startsWith(ADM+path.sep))return send(r,403,'Forbidden','text/plain');
 fs.readFile(f,(e,d)=>{if(e){d=fromEmbed(path.relative(__dirname,f).split(path.sep).join('/'));if(!d){console.log('404 '+u+' -> '+f);return send(r,404,'Not found','text/plain')}}
 send(r,200,d,types[path.extname(f)]||'application/octet-stream',{'Cache-Control':f.endsWith('.jpg')?'public, max-age=86400':'no-cache'})});
}).on('error',e=>{console.log(e.code=='EADDRINUSE'?`Port ${PORT} is already in use. Close the other server window, or run:  set PORT=3001  then  node server.js`:e.message);process.exit(1)})
.listen(PORT,()=>{console.log('Public site: http://localhost:'+PORT+'\nAdmin panel: http://localhost:'+PORT+'/admin');if(PW=='ECS2026')console.log('Warning: default admin password in use. Set ADMIN_PASSWORD before going online.')});
